28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const PROCESSING_FEE = 5;
38	
39	const WHOLE_PERCENT = 100;
40	
41	/**
42	 * Surcharges multiply before dividing, so the arithmetic stays exact.
43	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
44	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
45	 * instead of 115 G.
46	 */
47	const addSurcharge = (amount: number, surchargePercent: number): number =>
48	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
49	
50	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
51	
52	/** All rounding is in the MHPCO's favor — always up. */
53	const roundInMHPCOsFavor = Math.ceil;
54	
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_PREMIUM = 60;
57	
58	const isBuildingBlock = (items: InsuredItem[]): boolean =>
59	  items.length === BUILDING_BLOCK_SIZE &&
60	  items.every((item) => item.type === items[0].type);
61	
62	const sumBasePremiums = (items: InsuredItem[]): number => {
63	  if (isBuildingBlock(items)) return BUILDING_BLOCK_PREMIUM;
64	
65	  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
66	};
67	
68	/**
69	 * The premium pipeline, in the order the spec states it: sum the base
70	 * premiums, apply surcharges, round, then add the processing fee last.
71	 */
72	const quotePremium = (step: Step): QuoteResult => {
73	  const basePremium = sumBasePremiums(step.items ?? []);
74	  const surcharged = addSurcharge(
75	    basePremium,
76	    FIRST_INSURANCE_SURCHARGE_PERCENT,
77	  );
78	
79	  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
80	};
81	
82	export const runScenario = (scenario: Scenario): ScenarioResults => ({
83	  results: scenario.steps.map(quotePremium),
84	});
